"use client";

import { useRef, useEffect } from "react";
import Link from "next/link";
import Image from "next/image";
import { LangProvider, useLang } from "@/app/i18n";
import { motion, useScroll, useTransform } from "framer-motion";
import { ArrowLeft } from "lucide-react";
import CustomCursor from "@/components/CustomCursor";
import Lenis from "lenis";

function ProjectsContent() {
  const { t } = useLang();
  const horizontalRef = useRef<HTMLDivElement>(null);

  /* Lenis smooth scroll */
  useEffect(() => {
    const lenis = new Lenis({
      duration: 1.4,
      easing: (t: number) => Math.min(1, 1.001 - Math.pow(2, -10 * t)),
    });
    function raf(time: number) {
      lenis.raf(time);
      requestAnimationFrame(raf);
    }
    requestAnimationFrame(raf);
    return () => lenis.destroy();
  }, []);

  const { scrollYProgress } = useScroll({ 
    target: horizontalRef,
    offset: ["start start", "end end"]
  });
  const x = useTransform(scrollYProgress, [0, 1], ["0%", "-80%"]);

  const opacity1 = useTransform(scrollYProgress, [0.10, 0.25, 0.35, 0.50], [0, 0.6, 0.6, 0]);
  const opacity2 = useTransform(scrollYProgress, [0.30, 0.45, 0.55, 0.70], [0, 0.6, 0.6, 0]);
  const opacity3 = useTransform(scrollYProgress, [0.50, 0.65, 0.75, 0.90], [0, 0.6, 0.6, 0]);

  const scale1 = useTransform(scrollYProgress, [0.10, 0.50], [1.08, 1.18]);
  const scale2 = useTransform(scrollYProgress, [0.30, 0.70], [1.08, 1.18]);
  const scale3 = useTransform(scrollYProgress, [0.50, 0.90], [1.08, 1.18]);

  return (
    <main className="relative bg-[#020617]">
      <CustomCursor />
      
      {/* Navigation */}
      <nav className="fixed top-0 w-full px-6 md:px-12 py-8 flex justify-between items-center z-50 mix-blend-difference">
        <Link href="/" className="hoverable flex items-center gap-3 text-white/50 hover:text-white transition-colors group">
          <div className="w-10 h-10 rounded-full border border-white/20 flex items-center justify-center group-hover:border-brandOrange group-hover:bg-brandOrange/10 transition-all duration-300">
            <ArrowLeft className="w-4 h-4 group-hover:-translate-x-1 transition-transform" />
          </div>
          <span className="font-mono text-[10px] font-bold uppercase tracking-[0.2em]">Volver al Inicio</span>
        </Link>
        <div className="font-display font-black text-xl tracking-widest uppercase opacity-50 text-white">
          3Tree<span className="text-brandOrange">.</span>
        </div>
      </nav>

      {/* HORIZONTAL SCROLL PROJECTS */}
      <section id="projects" ref={horizontalRef} className="h-[400vh] relative">
        <div className="sticky top-0 flex h-screen items-center overflow-hidden">
          
          {/* Background Images */}
          <div className="absolute inset-0 z-0 pointer-events-none">
            {/* Image 1 - Gridiron AI */}
            <motion.div 
              className="absolute inset-0"
              style={{
                WebkitMaskImage: 'radial-gradient(ellipse 80% 80% at 50% 50%, black 20%, transparent 70%)',
                maskImage: 'radial-gradient(ellipse 80% 80% at 50% 50%, black 20%, transparent 70%)',
                opacity: opacity1,
                scale: scale1
              }}
            >
              <Image src="/hero-football.jpg" alt="Biomechanics" fill quality={100} className="object-cover object-top opacity-60 mix-blend-screen" />
            </motion.div>

            {/* Image 2 - System Data */}
            <motion.div 
              className="absolute inset-0"
              style={{
                WebkitMaskImage: 'radial-gradient(ellipse 80% 80% at 50% 50%, black 20%, transparent 70%)',
                maskImage: 'radial-gradient(ellipse 80% 80% at 50% 50%, black 20%, transparent 70%)',
                opacity: opacity2,
                scale: scale2
              }}
            >
              <Image src="/computer_vision_thumb_1784602244275.jpg" alt="System Data" fill quality={100} className="object-cover object-center opacity-60 mix-blend-screen" />
            </motion.div>

            {/* Image 3 - Ice Analytics */}
            <motion.div 
              className="absolute inset-0"
              style={{
                WebkitMaskImage: 'radial-gradient(ellipse 80% 80% at 50% 50%, black 20%, transparent 70%)',
                maskImage: 'radial-gradient(ellipse 80% 80% at 50% 50%, black 20%, transparent 70%)',
                opacity: opacity3,
                scale: scale3
              }}
            >
              <Image src="/hero-hockey.jpg" alt="Ice Analytics" fill quality={100} className="object-cover object-center opacity-60 mix-blend-screen" />
            </motion.div>
          </div>

          <motion.div style={{ x }} className="flex w-[400vw] z-10 relative">

            {/* Panel 1 - Title */}
            <div className="w-screen h-screen flex flex-col justify-center items-center text-center px-6 md:px-20 shrink-0">
              <motion.span initial={{ opacity: 0 }} whileInView={{ opacity: 1 }} className="text-brandOrange font-mono text-[11px] tracking-[0.4em] uppercase font-bold mb-8 inline-flex items-center gap-3">
                <span className="w-8 h-[1px] bg-brandOrange"></span> {t.caseStudy}
              </motion.span>
              <h2 className="font-display text-6xl md:text-[10rem] font-black uppercase text-white leading-none mb-6 orange-blur-text" data-text={t.scoutAi}>{t.scoutAi}</h2>
              <h3 className="font-display text-3xl md:text-5xl font-bold uppercase text-brandOrange mb-8">{t.pro}</h3>
              <p className="text-white/30 max-w-md text-base font-medium">{t.exploreScroll}</p>
            </div>

            {/* Panel 2 - Phase 1 */}
            <div className="w-screen h-screen flex flex-col md:flex-row justify-center items-center shrink-0 relative px-10 md:px-24 group gap-10">
               <div className="w-full md:w-1/2 flex flex-col justify-center items-start md:pl-10 relative z-10 md:mr-auto">
                  <span className="text-brandOrange font-mono tracking-[0.3em] uppercase text-[10px] font-bold mb-4 flex items-center gap-2">
                     <span className="w-4 h-[1px] bg-brandOrange"></span> {t.phase1}
                  </span>
                  <h3 className="text-5xl md:text-7xl font-display font-black text-white uppercase mb-6 leading-none drop-shadow-2xl">{t.project1Title[0]} <br/> {t.project1Title[1]}</h3>
                  <p className="text-white/40 text-lg max-w-md drop-shadow-lg">{t.phase1Desc}</p>
               </div>
            </div>

            {/* Panel 3 - Phase 2 */}
            <div className="w-screen h-screen flex flex-col md:flex-row justify-center items-center shrink-0 relative px-10 md:px-24 group gap-10">
               <div className="w-full md:w-1/2 flex flex-col justify-center items-end text-right md:pr-10 relative z-10 md:ml-auto">
                  <span className="text-brandOrange font-mono tracking-[0.3em] uppercase text-[10px] font-bold mb-4 flex items-center gap-2">
                     {t.phase2} <span className="w-4 h-[1px] bg-brandOrange"></span>
                  </span>
                  <h3 className="text-5xl md:text-7xl font-display font-black text-white uppercase mb-6 leading-none drop-shadow-2xl">{t.project2Title[0]} <br/> {t.project2Title[1]}</h3>
                  <p className="text-white/40 text-lg max-w-md drop-shadow-lg">{t.phase2Desc}</p>
               </div>
            </div>

            {/* Panel 4 - Phase 3 */}
            <div className="w-screen h-screen flex flex-col md:flex-row justify-center items-center shrink-0 relative px-10 md:px-24 group gap-10">
               <div className="w-full md:w-1/2 flex flex-col justify-center items-start md:pl-10 relative z-10 md:mr-auto">
                  <span className="text-brandBlue font-mono tracking-[0.3em] uppercase text-[10px] font-bold mb-4 flex items-center gap-2">
                     <span className="w-4 h-[1px] bg-brandBlue"></span> {t.phase3}
                  </span>
                  <h3 className="text-5xl md:text-7xl font-display font-black text-white uppercase mb-6 leading-none drop-shadow-2xl">{t.project3Title[0]} <br/> {t.project3Title[1]}</h3>
                  <p className="text-white/40 text-lg max-w-md drop-shadow-lg">{t.phase3Desc}</p>
               </div>
            </div>

          </motion.div>
        </div>
      </section>
    </main>
  );
}

export default function ProjectsPage() {
  return (
    <LangProvider>
      <ProjectsContent />
    </LangProvider>
  );
}
